class Solution:
    def subsets(self, nums: List[int]) -> List[List[int]]:
        n = len(nums)
        ans = []
        for mask in range(1 << n):
            t = []
            for i in range(n):
                if mask >> i & 1:
                    t.append(nums[i])
            ans.append(t)
        return ans

class Solution:
    def subsets(self, nums: List[int]) -> List[List[int]]:
        ans, t = [], []

        def dfs(cur: int) -> None:
            if cur == len(nums):
                ans.append(t[:])
                return
            t.append(nums[cur])
            dfs(cur + 1)
            t.pop()
            dfs(cur + 1)

        dfs(0)
        return ans
